/**
 * Everything the Data Management screen does to Supabase.
 *
 * Kept out of the component so the screen is only presentation, and so each
 * operation can say precisely what went wrong. "Something failed" is useless to
 * somebody who cannot open a terminal, and the person using this screen by
 * design cannot: they have no Massive key, no Supabase credentials, no shell
 * and no deploy access. If a refresh does not work, this file's error messages
 * are the entire diagnosis available to them.
 *
 * WHAT THIS DELIBERATELY CANNOT DO
 * Nothing here reads or writes the Massive API key. It cannot: the key exists
 * only as a secret on the Edge Function, which is a separate process this code
 * can only POST to. The screen triggers ingestion; it never performs it.
 */

import { getSupabase, functionUrl, isConfigured } from "./supabase.js"

/** A failure a human can act on. */
export class AdminError extends Error {
  constructor(message, { hint, cause } = {}) {
    super(message)
    this.name = "AdminError"
    this.hint = hint
    this.cause = cause
  }
}

const NOT_CONFIGURED = new AdminError("Supabase is not connected.", {
  hint:
    "GATSBY_SUPABASE_URL and GATSBY_SUPABASE_ANON_KEY are not set on this build. " +
    "The terminal is running on its bundled data — everything works, it just cannot refresh.",
})

function need() {
  const db = getSupabase()
  if (!db) throw NOT_CONFIGURED
  return db
}

/* ------------------------------------------------------------------ auth -- */

export async function signIn(email, password) {
  const db = need()
  const { data, error } = await db.auth.signInWithPassword({ email, password })
  if (error) {
    throw new AdminError(
      error.message === "Invalid login credentials"
        ? "That email and password did not match an account."
        : error.message,
      { hint: "Accounts are created in Supabase → Authentication → Users." }
    )
  }
  return data.user
}

export async function signOut() {
  const db = getSupabase()
  if (db) await db.auth.signOut()
}

export async function currentUser() {
  const db = getSupabase()
  if (!db) return null
  const { data } = await db.auth.getUser()
  return data?.user ?? null
}

/**
 * Is the signed-in user on the allowlist?
 *
 * The allowlist table is readable only by admins, so a non-admin's select comes
 * back empty rather than forbidden. That means "no rows" is the answer for both
 * "not an admin" and "table is empty", which is why a fresh project needs its
 * first admin inserted from the Supabase dashboard — bootstrapping one from the
 * browser would mean a policy that lets anyone add themselves.
 */
export async function isAdmin() {
  const db = getSupabase()
  if (!db) return false
  const { data } = await db.rpc("is_admin")
  return data === true
}

export function onAuthChange(handler) {
  const db = getSupabase()
  if (!db) return () => {}
  const { data } = db.auth.onAuthStateChange((_event, session) => handler(session?.user ?? null))
  return () => data.subscription.unsubscribe()
}

/* ---------------------------------------------------------------- status -- */

/**
 * The header summary: when, how many, how much.
 *
 * Reads the view rather than counting client-side so the numbers are the
 * database's own and cannot drift from what ingestion actually wrote.
 */
export async function getDataStatus() {
  const db = need()
  const { data, error } = await db.from("data_status").select("*").maybeSingle()
  if (error) throw new AdminError("Could not read the data summary.", { cause: error })
  return data
}

/** Per-dataset coverage, so a stale or missing series is visible by symbol. */
export async function getCoverage() {
  const db = need()
  const { data, error } = await db
    .from("market_data")
    .select("symbol, kind, bar_count, first_bar, last_bar, bytes, ingested_at")
    .order("symbol")
  if (error) throw new AdminError("Could not read dataset coverage.", { cause: error })
  return data ?? []
}

export async function getUniverse() {
  const db = need()
  const { data, error } = await db
    .from("universe")
    .select("symbol, name, enabled, sort_order, added_at")
    .order("sort_order")
  if (error) throw new AdminError("Could not read the universe.", { cause: error })
  return data ?? []
}

export async function getSettings() {
  const db = need()
  const { data, error } = await db.from("app_settings").select("key, value, updated_at, updated_by")
  if (error) throw new AdminError("Could not read settings.", { cause: error })
  const out = {}
  for (const row of data ?? []) out[row.key] = row.value
  return out
}

/** Recent jobs, newest first — running, completed and failed alike. */
export async function getJobs(limit = 10) {
  const db = need()
  const { data, error } = await db
    .from("ingest_jobs")
    .select(
      "id, status, triggered_by, symbols, minute_sessions, calls_made, calls_cached, " +
        "progress, completed, total, failures, started_at, finished_at, duration_ms, error, result"
    )
    .order("started_at", { ascending: false })
    .limit(limit)
  if (error) {
    throw new AdminError("Could not read ingestion history.", {
      hint: "Job history is admin-only. If you are signed in, your email may not be on the allowlist.",
      cause: error,
    })
  }
  return data ?? []
}

/* ----------------------------------------------------------------- edits -- */

export async function setSymbolEnabled(symbol, enabled) {
  const db = need()
  const { error } = await db
    .from("universe")
    .update({ enabled, updated_at: new Date().toISOString() })
    .eq("symbol", symbol)
  if (error) throw new AdminError(`Could not update ${symbol}.`, { cause: error })
}

export async function addSymbol(symbol, name = null) {
  const db = need()
  const clean = String(symbol || "").trim().toUpperCase()
  if (!/^[A-Z][A-Z0-9.\-]{0,9}$/.test(clean)) {
    throw new AdminError(`"${symbol}" is not a valid ticker.`, {
      hint: "Tickers are 1–10 characters, starting with a letter.",
    })
  }

  const { data: existing } = await db.from("universe").select("symbol").eq("symbol", clean).maybeSingle()
  if (existing) throw new AdminError(`${clean} is already in the universe.`)

  const { data: last } = await db
    .from("universe")
    .select("sort_order")
    .order("sort_order", { ascending: false })
    .limit(1)
    .maybeSingle()

  const { error } = await db
    .from("universe")
    .insert({ symbol: clean, name, sort_order: (last?.sort_order ?? 0) + 1 })
  if (error) throw new AdminError(`Could not add ${clean}.`, { cause: error })

  /*
   * A newly added symbol has no data until the next ingestion. Saying so here
   * matters: the alternative is a ticker that appears in the universe, shows
   * nothing anywhere, and looks broken rather than pending.
   */
  return { symbol: clean, needsIngest: true }
}

export async function removeSymbol(symbol) {
  const db = need()
  const { error } = await db.from("universe").delete().eq("symbol", symbol)
  if (error) throw new AdminError(`Could not remove ${symbol}.`, { cause: error })

  // Its stored series are left in place on purpose — removing a symbol from
  // the scan universe is not the same as wanting its history destroyed, and
  // re-adding it should not have to re-spend quota.
}

export async function setMinuteSessions(count) {
  const db = need()
  const n = Math.max(1, Math.min(20, Math.floor(Number(count) || 5)))
  const { error } = await db
    .from("app_settings")
    .update({ value: n, updated_at: new Date().toISOString() })
    .eq("key", "minute_sessions")
  if (error) throw new AdminError("Could not save the session count.", { cause: error })
  return n
}

/* --------------------------------------------------------------- ingest -- */

/**
 * Call the ingest Edge Function.
 *
 * The user's access token goes in the Authorization header; the function
 * verifies it against the allowlist itself, because it runs as the service role
 * and so is not covered by row level security.
 */
async function callIngest(action, body = {}) {
  if (!isConfigured) throw NOT_CONFIGURED
  const db = need()

  const { data: sessionData } = await db.auth.getSession()
  const token = sessionData?.session?.access_token
  if (!token) throw new AdminError("You are signed out. Sign in again to continue.")

  let response
  try {
    response = await fetch(functionUrl("ingest"), {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
      body: JSON.stringify({ action, ...body }),
    })
  } catch (cause) {
    throw new AdminError("Could not reach the ingestion function.", {
      hint: "It may not be deployed yet — `supabase functions deploy ingest`.",
      cause,
    })
  }

  let payload = {}
  try {
    payload = await response.json()
  } catch {
    // A non-JSON body from an Edge Function is almost always a platform-level
    // error page, which the status code describes better than the body would.
  }

  if (!response.ok) {
    throw new AdminError(payload.error || `Ingestion failed (${response.status}).`, {
      hint:
        response.status === 403
          ? "Your account is not on the Data Management allowlist."
          : payload.detail,
    })
  }
  return payload
}

export const startIngest = opts => callIngest("start", opts)
export const continueIngest = () => callIngest("continue")
export const cancelIngest = () => callIngest("cancel")

/**
 * Drive a job to completion, reporting progress as it goes.
 *
 * One invocation of the function drains for about fifty seconds and then
 * returns, because a full pass at 5 calls a minute takes roughly seventeen and
 * no Edge Function lives that long. So the browser re-invokes until the queue
 * is empty. The tab must stay open — which is worth saying in the UI, and is
 * why `onProgress` exists rather than a spinner.
 */
export async function runIngestToCompletion({ onProgress, minuteSessions, signal } = {}) {
  let result = await startIngest(minuteSessions ? { minuteSessions } : {})
  onProgress?.(result)

  while (result.status === "running" && result.remaining > 0) {
    if (signal?.aborted) return { ...result, stopped: true }
    result = await continueIngest()
    onProgress?.(result)
  }
  return result
}
