/**
 * Real fundamentals, adapted from Massive's SEC-derived financial statements.
 *
 * Massive returns each filing as four statements (income, balance sheet, cash
 * flow, comprehensive income), every line item wrapped as
 * `{ value, unit, label, order }`. This module flattens that into the shape the
 * UI already expects and, critically, distinguishes THREE states rather than
 * two:
 *
 *   - a real number from the filing
 *   - `null` because the filing genuinely does not report that line
 *   - `undefined` because no filing was ingested at all
 *
 * Collapsing "not reported" into zero is how a fundamentals screen ends up
 * claiming a company had no debt.
 *
 * NOT DERIVABLE FROM THIS FEED: capital expenditure is absent, so free cash
 * flow cannot be computed. We surface operating cash flow instead and label it
 * as such rather than passing one off as the other.
 */

import { getRealFinancials } from "./source.js"

/** Pull a line item's numeric value, or null when the filing omits it. */
function line(statement, key) {
  if (!statement) return null
  const entry = statement[key]
  if (!entry || typeof entry.value !== "number" || !Number.isFinite(entry.value)) return null
  return entry.value
}

function safeDiv(a, b) {
  if (!Number.isFinite(a) || !Number.isFinite(b) || b === 0) return null
  const v = a / b
  return Number.isFinite(v) ? v : null
}

/** Margins on negligible revenue are arithmetically valid but meaningless. */
function margin(numerator, revenue) {
  const v = safeDiv(numerator, revenue)
  if (v === null) return null
  return Math.abs(v) > 10 ? null : v
}

function growth(prev, curr) {
  if (!Number.isFinite(prev) || !Number.isFinite(curr) || prev <= 0) return null
  return (curr - prev) / prev
}

function cagr(start, end, years) {
  if (!Number.isFinite(start) || !Number.isFinite(end)) return null
  if (start <= 0 || end <= 0 || years <= 0) return null
  const v = Math.pow(end / start, 1 / years) - 1
  return Number.isFinite(v) ? v : null
}

/**
 * One filing → one normalised annual period.
 */
function adaptPeriod(filing) {
  const f = filing.financials || {}
  const income = f.income_statement
  const balance = f.balance_sheet
  const cash = f.cash_flow_statement

  const revenue = line(income, "revenues")
  const netIncome = line(income, "net_income_loss")

  /*
   * DILUTED first, then basic.
   *
   * Diluted is the conservative figure — it assumes every option, warrant and
   * convertible that is in the money gets exercised — and it is what a P/E is
   * quoted on by convention. Preferring basic inflates EPS and therefore
   * flatters the P/E: AAPL FY2025 is 7.49 basic against 7.46 diluted, so the
   * ratio came out 0.4% cheaper than the market's own. Small on AAPL; not
   * small on a company with heavy option issuance, which is exactly the kind
   * of company a screen is supposed to catch.
   */
  const shares = line(income, "diluted_average_shares") ?? line(income, "basic_average_shares")
  let eps = line(income, "diluted_earnings_per_share")
  if (eps === null || eps === 0) eps = line(income, "basic_earnings_per_share")
  if ((eps === null || eps === 0) && netIncome !== null && shares) {
    eps = safeDiv(netIncome, shares)
  }

  return {
    year: filing.fiscal_year ? Number(filing.fiscal_year) : null,
    period: filing.fiscal_period || null,
    endDate: filing.end_date || null,
    filingDate: filing.filing_date || null,

    revenue,
    costOfRevenue: line(income, "cost_of_revenue"),
    grossProfit: line(income, "gross_profit"),
    operatingIncome: line(income, "operating_income_loss"),
    operatingExpenses: line(income, "operating_expenses"),
    researchAndDevelopment: line(income, "research_and_development"),
    incomeTax: line(income, "income_tax_expense_benefit"),
    netIncome,
    eps,
    sharesBasic: shares,
    sharesDiluted: line(income, "diluted_average_shares"),

    totalAssets: line(balance, "assets"),
    currentAssets: line(balance, "current_assets"),
    inventory: line(balance, "inventory"),
    totalLiabilities: line(balance, "liabilities"),
    currentLiabilities: line(balance, "current_liabilities"),
    longTermDebt: line(balance, "long_term_debt"),
    totalEquity: line(balance, "equity"),

    operatingCashFlow: line(cash, "net_cash_flow_from_operating_activities"),
    investingCashFlow: line(cash, "net_cash_flow_from_investing_activities"),
    financingCashFlow: line(cash, "net_cash_flow_from_financing_activities"),
    netCashFlow: line(cash, "net_cash_flow"),

    // Capex is not in this feed, so free cash flow is genuinely unavailable.
    freeCashFlow: null,
  }
}

/**
 * Normalised annual history for a symbol, oldest first, or null when nothing
 * was ingested. Annual periods only — quarterlies would mix reporting bases in
 * the year-over-year figures.
 */
export function getFundamentals(symbol) {
  const raw = getRealFinancials(symbol)
  if (!raw || !raw.length) return null

  const periods = raw
    .filter(f => (f.fiscal_period || "").toUpperCase() === "FY")
    .map(adaptPeriod)
    .filter(p => p.year && p.revenue !== null)
    .sort((a, b) => a.year - b.year)

  return periods.length ? periods : null
}

/**
 * Ratios derived from the real filings, in the shape companies.js already uses.
 * Returns null when there are no filings, so the caller keeps its fallback.
 */
export function getDerivedFundamentals(symbol) {
  const periods = getFundamentals(symbol)
  if (!periods || periods.length < 1) return null

  const last = periods[periods.length - 1]
  const prev = periods.length > 1 ? periods[periods.length - 2] : null
  const start3 = periods.length >= 4 ? periods[periods.length - 4] : null
  const start5 = periods[0]
  const spanYears = Math.max(1, periods.length - 1)

  return {
    source: "massive-financials",
    periodsAvailable: periods.length,
    latestFiscalYear: last.year,
    latestPeriodEnd: last.endDate,

    // The five-year table the UI renders.
    financials: periods.map(p => ({
      year: p.year,
      revenue: p.revenue,
      netIncome: p.netIncome,
      eps: p.eps,
    })),

    revenueTTM: last.revenue,
    netIncomeTTM: last.netIncome,
    epsTTM: last.eps,
    grossProfit: last.grossProfit,

    grossMargin: margin(last.grossProfit, last.revenue),
    operatingMargin: margin(last.operatingIncome, last.revenue),
    netMargin: margin(last.netIncome, last.revenue),
    /*
     * ROE is only meaningful on positive equity. LUNR carries -$0.75B of equity
     * against a loss, and net-negative over equity-negative yields a cheerful
     * +14.2% — a number that reads as strong performance and means the opposite.
     * Null is the honest answer.
     */
    roe:
      Number.isFinite(last.totalEquity) && last.totalEquity > 0
        ? safeDiv(last.netIncome, last.totalEquity)
        : null,
    roa: safeDiv(last.netIncome, last.totalAssets),

    revenueGrowthYoY: prev ? growth(prev.revenue, last.revenue) : null,
    epsGrowthYoY: prev ? growth(prev.eps, last.eps) : null,
    revenueCagr3y: start3 ? cagr(start3.revenue, last.revenue, 3) : null,
    epsCagr3y: start3 ? cagr(start3.eps, last.eps, 3) : null,
    revenueCagr5y: cagr(start5.revenue, last.revenue, spanYears),
    epsCagr5y: cagr(start5.eps, last.eps, spanYears),

    totalAssets: last.totalAssets,
    totalEquity: last.totalEquity,
    totalDebt: last.longTermDebt,
    operatingCashFlow: last.operatingCashFlow,

    /*
     * Deliberately null, not zero. Capex is absent from this feed, so free cash
     * flow cannot be computed — and a fundamentals screen that prints "$0.00"
     * where it means "not reported" is worse than one that prints an em dash.
     */
    freeCashFlow: null,
    unavailable: ["freeCashFlow", "totalCash", "dividendYield", "forwardPE"],

    periods,
  }
}

/* ==========================================================================
   SEC filings  (SMT-007)
   ==========================================================================

   Available on the free tier, so this tab must work rather than be locked.

   Every filing the financials feed returns carries its SEC ACCESSION NUMBER
   inside source_filing_url — "0000320193-25-000079". That is the real,
   citable identity of the document, and it is what turns a row in a table into
   something the client can click through to EDGAR and check for themselves.
   Rendering the period without the link would be a list of dates.
   ========================================================================== */

/** Pulls the accession number out of a Massive filing URL, or null. */
export function accessionFrom(url) {
  if (typeof url !== "string") return null
  const match = /(\d{10}-\d{2}-\d{6})/.exec(url)
  return match ? match[1] : null
}

/** The public EDGAR page for a filing, built from CIK + accession. */
export function edgarUrl(cik, accession) {
  if (!cik || !accession) return null
  // EDGAR wants the CIK without leading zeros and the accession without dashes.
  const cleanCik = String(cik).replace(/^0+/, "")
  const cleanAccession = accession.replace(/-/g, "")
  return `https://www.sec.gov/Archives/edgar/data/${cleanCik}/${cleanAccession}/`
}

/**
 * The filings behind a symbol's financials, newest first.
 *
 * Returns [] when there are none — an empty list is a factual answer here, and
 * the caller distinguishes it from "locked" on its own.
 */
export function getSecFilings(symbol) {
  const raw = getRealFinancials(symbol)
  if (!Array.isArray(raw) || !raw.length) return []

  return raw
    .map(filing => {
      const accession = accessionFrom(filing.source_filing_url || filing.source_filing_file_url)
      return {
        accession,
        cik: filing.cik ?? null,
        companyName: filing.company_name ?? null,
        fiscalYear: filing.fiscal_year ? Number(filing.fiscal_year) : null,
        fiscalPeriod: filing.fiscal_period ?? null,
        // An annual filing is a 10-K, a quarter is a 10-Q. The feed reports the
        // period rather than the form type, so the label is derived and says so.
        formType: filing.fiscal_period === "FY" ? "10-K" : "10-Q",
        filingDate: filing.filing_date ?? null,
        periodStart: filing.start_date ?? null,
        periodEnd: filing.end_date ?? null,
        edgarUrl: edgarUrl(filing.cik, accession),
        sourceUrl: filing.source_filing_url ?? null,
      }
    })
    .sort((a, b) => String(b.filingDate ?? "").localeCompare(String(a.filingDate ?? "")))
}
