/**
 * Initials for an account avatar.
 *
 * Its own module, free of React and Gatsby imports, so it can be unit-tested
 * directly. The alternative — asserting on the source text of a component that
 * cannot be imported in Node — tests that the code was written a certain way
 * rather than that it produces the right answer, which is a different and much
 * weaker claim.
 */

/**
 * Two letters identifying an email address.
 *
 * A dotted, underscored or hyphenated local part is treated as a name, so
 * "jane.doe@x.com" gives "JD". Otherwise the local part and the domain each
 * contribute a letter — "scanner@kahdel..." gives "SK" — which separates
 * accounts far better than two letters from the same word would, since several
 * accounts on one deployment often share a local part.
 */
export function initialsFor(email) {
  if (!email || typeof email !== "string") return "?"

  const trimmed = email.trim()
  if (!trimmed) return "?"

  const at = trimmed.indexOf("@")
  const local = at === -1 ? trimmed : trimmed.slice(0, at)
  const domain = at === -1 ? "" : trimmed.slice(at + 1)

  const parts = local.split(/[._+-]+/).filter(Boolean)

  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase()
  if (parts.length === 1 && domain) return (parts[0][0] + domain[0]).toUpperCase()
  if (parts.length === 1) return parts[0][0].toUpperCase()

  return "?"
}
