import React from "react"
import { INDICES } from "../../data/markets"

/**
 * The market summary bar under the main navigation.
 *
 * On the free Massive plan we are not entitled to index data (I:SPX returns
 * 403), so these are the ETFs that track each benchmark. That distinction is
 * shown, not hidden: SPY trades near $760 while the S&P 500 sits near 6,000, so
 * printing "S&P 500  762.60" would be a fabricated index level. Each item leads
 * with the ticker whose price is actually quoted and names the benchmark beside
 * it. The percentage change is the real, comparable figure either way.
 *
 * On narrow screens the row scrolls horizontally rather than wrapping.
 */

function formatValue(index) {
  if (index.format === "currency-compact") {
    return "$" + (index.value / 1000).toFixed(0) + "K"
  }
  if (index.format === "plain") {
    return index.value.toFixed(1)
  }
  // ETF prices keep their cents; an index level would not have any.
  return index.value.toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })
}

export default function MarketTicker() {
  return (
    <div className="ticker">
      <div className="ticker__inner">
        <ul className="ticker__list" aria-label="Market summary">
          {INDICES.map(index => (
            <li
              className="ticker__item"
              key={index.key}
              title={
                index.benchmark
                  ? `${index.symbol} — ${index.benchmark} proxy (index data is not included in this plan)`
                  : index.name
              }
            >
              <span className="ticker__name">
                {index.name}
                {index.benchmark && (
                  <span className="ticker__benchmark">{index.benchmark}</span>
                )}
              </span>
              <span className="ticker__row">
                <span className="ticker__value">{formatValue(index)}</span>
                <span className={"ticker__change ticker__change--" + index.direction}>
                  {index.changePct > 0 ? "+" : ""}
                  {index.changePct.toFixed(2)}%
                </span>
              </span>
            </li>
          ))}
        </ul>
      </div>
    </div>
  )
}
