import React, { useEffect, useRef, useState, useCallback } from "react"
import { Link } from "gatsby"

import { isConfigured } from "../../data/supabase.js"
import { currentUser, isAdmin, onAuthChange, signOut } from "../../data/admin.js"
import { initialsFor } from "./initials.js"

/**
 * The account control in the header.
 *
 * It used to be the two letters "AR", hardcoded, on a button that did nothing.
 * That is worse than having no avatar at all: it asserts an identity, and the
 * first person to notice it shows someone else's initials — or their own when
 * they are signed out — stops trusting the rest of the header too.
 *
 * So everything here comes from the live Supabase session. The initials are
 * derived from the signed-in email, the menu shows that email in full, and
 * whether the account can reach Data Management is stated rather than implied,
 * because being signed in and being allowlisted are genuinely different things
 * and the difference is otherwise invisible until a page refuses to load.
 */

const MENU_WIDTH = 260
const VIEWPORT_MARGIN = 12

export default function AccountMenu() {
  const [user, setUser] = useState(null)
  const [admin, setAdmin] = useState(false)
  const [open, setOpen] = useState(false)
  const [rect, setRect] = useState(null)
  const [busy, setBusy] = useState(false)

  const buttonRef = useRef(null)
  const panelRef = useRef(null)

  /* ---------------------------------------------------------- session -- */

  useEffect(() => {
    if (!isConfigured) return undefined

    let alive = true
    ;(async () => {
      const u = await currentUser()
      if (!alive) return
      setUser(u)
      if (u) setAdmin(await isAdmin())
    })()

    // Keeps the header in step with a sign-in that happened on another tab or
    // on the Data Management page, rather than only on a full reload.
    const off = onAuthChange(async next => {
      setUser(next)
      setAdmin(next ? await isAdmin() : false)
      setOpen(false)
    })

    return () => {
      alive = false
      off()
    }
  }, [])

  /* --------------------------------------------------------- position -- */

  /*
   * Fixed positioning, measured from the button — the same approach the nav
   * dropdowns use. The header is a horizontal scroll container, which makes it
   * a containing block on BOTH axes, so an absolutely positioned panel gets
   * clipped rather than overflowing. This was already found the hard way once.
   */
  const place = useCallback(() => {
    const node = buttonRef.current
    if (!node || typeof window === "undefined") return
    const box = node.getBoundingClientRect()
    const maxLeft = window.innerWidth - MENU_WIDTH - VIEWPORT_MARGIN
    setRect({
      top: box.bottom + 6,
      left: Math.max(VIEWPORT_MARGIN, Math.min(box.right - MENU_WIDTH, maxLeft)),
    })
  }, [])

  useEffect(() => {
    if (!open) return undefined
    place()

    const onDocClick = event => {
      if (buttonRef.current?.contains(event.target)) return
      if (panelRef.current?.contains(event.target)) return
      setOpen(false)
    }
    const onKey = event => {
      if (event.key === "Escape") setOpen(false)
    }

    document.addEventListener("mousedown", onDocClick)
    document.addEventListener("keydown", onKey)
    window.addEventListener("resize", place)
    window.addEventListener("scroll", place, true)

    return () => {
      document.removeEventListener("mousedown", onDocClick)
      document.removeEventListener("keydown", onKey)
      window.removeEventListener("resize", place)
      window.removeEventListener("scroll", place, true)
    }
  }, [open, place])

  /* ---------------------------------------------------------- actions -- */

  const handleSignOut = async () => {
    setBusy(true)
    try {
      await signOut()
      setUser(null)
      setAdmin(false)
      setOpen(false)
    } finally {
      setBusy(false)
    }
  }

  /*
   * With no Supabase connection there is no such thing as being signed in, so
   * an account control would be a button that can never do anything. Rendering
   * nothing is the honest answer.
   */
  if (!isConfigured) return null

  const email = user?.email || null
  const label = email ? `Account: ${email}` : "Sign in"

  return (
    <>
      <button
        ref={buttonRef}
        type="button"
        className={"header__avatar" + (email ? "" : " header__avatar--anon")}
        aria-label={label}
        aria-haspopup="menu"
        aria-expanded={open}
        onClick={() => setOpen(v => !v)}
      >
        {email ? (
          initialsFor(email)
        ) : (
          /* A neutral mark, not initials — there is nobody to take them from. */
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true">
            <circle cx="12" cy="8" r="3.4" stroke="currentColor" strokeWidth="1.8" />
            <path
              d="M5 20c0-3.3 3.1-5.5 7-5.5s7 2.2 7 5.5"
              stroke="currentColor"
              strokeWidth="1.8"
              strokeLinecap="round"
            />
          </svg>
        )}
      </button>

      {open && rect && (
        <div
          ref={panelRef}
          className="account-menu"
          role="menu"
          style={{ top: rect.top, left: rect.left, width: MENU_WIDTH }}
        >
          {email ? (
            <>
              <div className="account-menu__identity">
                <span className="account-menu__avatar">{initialsFor(email)}</span>
                <span className="account-menu__who">
                  <span className="account-menu__email" title={email}>
                    {email}
                  </span>
                  <span
                    className={
                      "account-menu__role" + (admin ? " account-menu__role--admin" : "")
                    }
                  >
                    {admin ? "Data Management access" : "Signed in · no admin access"}
                  </span>
                </span>
              </div>

              {admin && (
                <Link className="account-menu__item" to="/admin/data/" role="menuitem">
                  Data Management
                </Link>
              )}

              {/*
                Stated plainly rather than left to be discovered. An account
                that signs in successfully but cannot open Data Management
                looks broken; saying why turns it into a request somebody can
                act on.
              */}
              {!admin && (
                <p className="account-menu__note">
                  This account is not on the Data Management allowlist. An existing
                  admin can add it.
                </p>
              )}

              <button
                type="button"
                className="account-menu__item account-menu__item--danger"
                role="menuitem"
                onClick={handleSignOut}
                disabled={busy}
              >
                {busy ? "Signing out…" : "Sign out"}
              </button>
            </>
          ) : (
            <>
              <p className="account-menu__note">
                Sign in to manage the data feed — refresh market data, edit the ticker
                universe and review past ingestion runs.
              </p>
              <Link className="account-menu__item" to="/admin/data/" role="menuitem">
                Sign in
              </Link>
            </>
          )}
        </div>
      )}
    </>
  )
}
