/**
 * Candle aggregation — building larger intraday candles from 1-minute bars.
 *
 * ---------------------------------------------------------------------------
 * THE TWO THINGS THAT MAKE AGGREGATION CORRECT
 * ---------------------------------------------------------------------------
 *
 * 1. BUCKETS ARE ANCHORED TO THE SESSION OPEN, NOT TO THE CLOCK.
 *    US equities open at 09:30 ET. An hourly candle therefore runs 09:30–10:30,
 *    not 09:00–10:00. Bucketing on wall-clock hours puts the open in a stub
 *    candle containing thirty minutes of the previous day's nothing, shifts
 *    every subsequent bar by half an interval, and quietly moves every
 *    indicator computed from them. Every platform a trader has ever used
 *    anchors to the open; so does this.
 *
 * 2. EACH FIELD AGGREGATES BY ITS OWN RULE.
 *      open   first bar's open        (not the mean)
 *      high   max of highs
 *      low    min of lows
 *      close  last bar's close
 *      volume sum
 *      vwap   VOLUME-WEIGHTED mean of the constituent VWAPs — not the plain
 *             average, which would let a 200-share minute count as much as a
 *             200,000-share one
 *      trades sum
 *    Averaging open/close, or taking a simple mean of VWAPs, produces candles
 *    that look plausible and are wrong in ways no chart makes visible.
 *
 * SESSIONS NEVER MERGE. A bucket is keyed by (session, index within session),
 * so the last candle of Monday and the first of Tuesday cannot combine into
 * one bar spanning the overnight gap.
 *
 * Pure arithmetic: no clock, no RNG, no I/O. Deterministic — the same bars in,
 * the same candles out, every time.
 */

import { sessionKey } from "../engine/vwap.js"

/** Regular US session open, in minutes past midnight ET. */
const SESSION_OPEN_MINUTES = 9 * 60 + 30

/**
 * The intervals a user can choose. `minutes: null` means "one bar per
 * session" — the daily candle, which is not built by bucketing.
 */
export const INTERVALS = [
  { key: "1m", minutes: 1, label: "1m", description: "One candle per minute" },
  { key: "5m", minutes: 5, label: "5m", description: "Five-minute candles" },
  { key: "15m", minutes: 15, label: "15m", description: "Fifteen-minute candles" },
  { key: "30m", minutes: 30, label: "30m", description: "Half-hour candles" },
  { key: "1h", minutes: 60, label: "1h", description: "Hourly candles, from the 09:30 open" },
  { key: "1D", minutes: null, label: "1D", description: "One candle per trading day" },
]

export const INTERVAL_KEYS = INTERVALS.map(i => i.key)
export const DEFAULT_INTERVAL = "5m"

export function getInterval(key) {
  return INTERVALS.find(i => i.key === key) || null
}

export function isIntradayInterval(key) {
  const interval = getInterval(key)
  return Boolean(interval && interval.minutes !== null)
}

function isNum(value) {
  return typeof value === "number" && Number.isFinite(value)
}

/** Minutes past midnight in New York, for a unix-seconds timestamp. */
const NY_TIME = new Intl.DateTimeFormat("en-US", {
  timeZone: "America/New_York",
  hour: "2-digit",
  minute: "2-digit",
  hour12: false,
})

function minutesIntoDay(time) {
  if (!isNum(time)) return null
  const ms = time > 1e11 ? time : time * 1000
  try {
    const [hh, mm] = NY_TIME.format(new Date(ms)).split(":")
    // "24" appears at exactly midnight in some ICU builds.
    const hours = Number(hh) % 24
    return hours * 60 + Number(mm)
  } catch {
    return null
  }
}

/**
 * Folds a run of bars into one candle.
 *
 * The bars must already be in ascending time order — the caller guarantees it,
 * because re-sorting here would hide a corrupted series rather than let it
 * show up as an obviously wrong chart.
 */
function foldBars(bars) {
  if (!bars.length) return null
  const first = bars[0]
  const last = bars[bars.length - 1]

  let high = -Infinity
  let low = Infinity
  let volume = 0
  let trades = 0
  let pv = 0 // Σ vwap·volume, for the volume-weighted VWAP
  let vwapVolume = 0

  for (const b of bars) {
    if (isNum(b.high) && b.high > high) high = b.high
    if (isNum(b.low) && b.low < low) low = b.low
    if (isNum(b.volume) && b.volume > 0) volume += b.volume
    if (isNum(b.trades)) trades += b.trades

    // A bar's VWAP only carries weight in proportion to the volume behind it.
    if (isNum(b.vwap) && b.vwap > 0 && isNum(b.volume) && b.volume > 0) {
      pv += b.vwap * b.volume
      vwapVolume += b.volume
    }
  }

  const candle = {
    time: first.time,
    open: first.open,
    high: Number.isFinite(high) ? high : Math.max(first.open, last.close),
    low: Number.isFinite(low) ? low : Math.min(first.open, last.close),
    close: last.close,
    volume,
  }

  // Only quote a VWAP when volume actually stood behind one. Falling back to a
  // plain mean would invent a level nothing traded at.
  if (vwapVolume > 0) candle.vwap = pv / vwapVolume
  if (trades > 0) candle.trades = trades

  return candle
}

/**
 * Aggregates 1-minute bars into `minutes`-sized candles.
 *
 * @param {Array} bars ascending 1-minute OHLCV, `time` in unix seconds
 * @param {number} minutes bucket size; 1 returns a copy of the input
 * @returns {Array} candles, ascending, never spanning a session boundary
 */
export function aggregateBars(bars, minutes) {
  if (!Array.isArray(bars) || !bars.length) return []
  const size = Math.floor(Number(minutes))
  if (!Number.isFinite(size) || size <= 1) return bars.slice()

  const out = []
  let bucket = []
  let bucketKey = null

  for (const b of bars) {
    const session = sessionKey(b.time)
    const mins = minutesIntoDay(b.time)
    if (session === null || mins === null) continue

    /*
     * Offset from the session open, so a 60-minute bucket starts at 09:30.
     * Pre-market bars (if a future ingest includes them) land in negative
     * offsets, and Math.floor keeps those bucketing consistently downward
     * rather than collapsing them all into bucket 0.
     */
    const offset = mins - SESSION_OPEN_MINUTES
    const index = Math.floor(offset / size)
    const key = session + "#" + index

    if (key !== bucketKey) {
      const folded = foldBars(bucket)
      if (folded) out.push(folded)
      bucket = []
      bucketKey = key
    }
    bucket.push(b)
  }

  const folded = foldBars(bucket)
  if (folded) out.push(folded)
  return out
}

/**
 * Collapses intraday bars into one candle per session.
 *
 * Used when a daily interval is asked for but only minute bars are held. The
 * daily ingest is still preferred where it exists — it is the venue's own
 * daily bar rather than our reconstruction of one.
 */
export function aggregateToDaily(bars) {
  if (!Array.isArray(bars) || !bars.length) return []
  const out = []
  let bucket = []
  let key = null

  for (const b of bars) {
    const session = sessionKey(b.time)
    if (session === null) continue
    if (session !== key) {
      const folded = foldBars(bucket)
      if (folded) out.push(folded)
      bucket = []
      key = session
    }
    bucket.push(b)
  }
  const folded = foldBars(bucket)
  if (folded) out.push(folded)
  return out
}

/**
 * How many candles a session of `sessionMinutes` yields at this interval.
 * The regular US session is 390 minutes, so 1h gives 7 buckets — six full
 * hours and a 30-minute stub at the close, which is what actually trades.
 */
export function candlesPerSession(intervalKey, sessionMinutes = 390) {
  const interval = getInterval(intervalKey)
  if (!interval || interval.minutes === null) return 1
  return Math.ceil(sessionMinutes / interval.minutes)
}
