import React, { useEffect, useRef, useState } from "react"
import { Link } from "gatsby"
import Icon, { LogoMark } from "../ui/Icon"
import { getMarketStatus } from "../../data/markets"
import AccountMenu from "./AccountMenu"

/**
 * Top navigation.
 *
 * Any nav item carrying `children` becomes a dropdown. State is keyed by LABEL
 * rather than held as a single boolean, because one boolean can only describe
 * one menu — a second dropdown added later would open and highlight in lockstep
 * with the first, which is the kind of bug that survives review because both
 * menus "work" in isolation.
 *
 * Which paths light a dropdown up is derived from its own children, so a new
 * entry cannot be forgotten in a second list.
 *
 * Both document listeners are attached inside useEffect, so nothing touches
 * `document` during the server render Gatsby performs at build time.
 */

const NAV = [
  { label: "Dashboard", to: "/" },
  { label: "Markets", to: "/markets/" },
  { label: "Scanner", to: "/scanner/" },
  {
    label: "Analysis",
    children: [
      { label: "Technical", to: "/technical/", desc: "Price action and indicators" },
      { label: "Fundamentals", to: "/fundamentals/", desc: "Valuation, growth and margins" },
      { label: "Delta", to: "/delta/", desc: "What changed, and by how much" },
    ],
  },
  {
    label: "Engine",
    children: [
      { label: "Strategies", to: "/strategies/", desc: "Backtests, parameter search, walk-forward" },
      { label: "Risk", to: "/risk/", desc: "How every live signal would be sized" },
    ],
  },
  { label: "Breakouts", to: "/breakouts/" },
  { label: "Watchlist", to: "/watchlist/" },
  { label: "News", to: "/news/" },
  { label: "Tutorials", to: "/tutorials/" },
  {
    label: "Admin",
    children: [
      {
        label: "Data Management",
        to: "/admin/data/",
        desc: "Ingestion, universe and storage",
      },
    ],
  },
]

const stripSlash = to => (to === "/" ? "/" : to.replace(/\/$/, ""))

/** Width the dropdown is laid out at; must match --dropdown-w in layout.css. */
const DROPDOWN_WIDTH = 232
const VIEWPORT_MARGIN = 12

export default function Header({ pathname = "" }) {
  /** The label of the open dropdown, or null. One menu open at a time. */
  const [openMenu, setOpenMenu] = useState(null)
  /**
   * Where to paint the open dropdown, in VIEWPORT coordinates.
   *
   * The dropdown cannot be positioned relative to its nav item, because
   * `.header__nav` carries `overflow-x: auto` — added to stop a too-wide nav
   * pushing the whole document sideways on tablet widths. The CSS spec does
   * not allow one axis to scroll while the other stays visible, so that rule
   * silently makes the nav a scroll container VERTICALLY too, and an
   * absolutely-positioned panel inside it is clipped to the 36px-tall nav box.
   * The button worked; the menu was rendered and invisible.
   *
   * So the panel is taken out of that box with `position: fixed` and told
   * where to go from the trigger's own bounding rect.
   */
  const [menuRect, setMenuRect] = useState(null)
  const [mobileOpen, setMobileOpen] = useState(false)
  const menuRefs = useRef(new Map())
  const status = getMarketStatus()

  const isActive = to => (to === "/" ? pathname === "/" : pathname.startsWith(stripSlash(to)))

  /** A dropdown is active when the current route is one of its own children. */
  const menuActive = item => (item.children || []).some(child => isActive(child.to))

  /** Measures the trigger and clamps the panel inside the viewport. */
  const positionMenu = label => {
    const node = menuRefs.current.get(label)
    if (!node) return
    const trigger = node.querySelector("button") || node
    const rect = trigger.getBoundingClientRect()
    const maxLeft = window.innerWidth - DROPDOWN_WIDTH - VIEWPORT_MARGIN
    setMenuRect({
      top: rect.bottom + 6,
      // Never let the panel run off the right edge on a narrow window.
      left: Math.max(VIEWPORT_MARGIN, Math.min(rect.left, maxLeft)),
    })
  }

  const toggleMenu = label => {
    setOpenMenu(current => {
      const next = current === label ? null : label
      if (next) positionMenu(label)
      else setMenuRect(null)
      return next
    })
  }

  useEffect(() => {
    if (!openMenu) return undefined

    function onPointerDown(event) {
      const node = menuRefs.current.get(openMenu)
      const panel = document.querySelector(".header__dropdown")
      // The panel is no longer a DOM descendant of the nav item, so a click
      // inside it would otherwise read as "outside" and close the menu before
      // the link could fire.
      if (panel && panel.contains(event.target)) return
      if (node && !node.contains(event.target)) setOpenMenu(null)
    }
    function onKeyDown(event) {
      if (event.key === "Escape") setOpenMenu(null)
    }
    // A fixed panel does not travel with the page, so it is repositioned
    // rather than left stranded beside a scrolled-away button.
    function reposition() {
      positionMenu(openMenu)
    }

    document.addEventListener("mousedown", onPointerDown)
    document.addEventListener("keydown", onKeyDown)
    window.addEventListener("resize", reposition)
    window.addEventListener("scroll", reposition, true)
    return () => {
      document.removeEventListener("mousedown", onPointerDown)
      document.removeEventListener("keydown", onKeyDown)
      window.removeEventListener("resize", reposition)
      window.removeEventListener("scroll", reposition, true)
    }
  }, [openMenu])

  // Any navigation closes every menu.
  useEffect(() => {
    setOpenMenu(null)
    setMobileOpen(false)
  }, [pathname])

  const flatItems = NAV.filter(i => !i.children)
  const menuItems = NAV.filter(i => i.children)

  return (
    <header className="header">
      <div className="header__inner">
        <Link className="header__brand" to="/">
          <span className="header__logo">
            <LogoMark size={20} />
          </span>
          <span className="header__wordmark">
            <span className="header__name">MarketScan</span>
            <span className="header__tagline">Find opportunity. Trade smarter.</span>
          </span>
        </Link>

        <nav className="header__nav" aria-label="Primary">
          {NAV.map(item => {
            if (item.children) {
              const open = openMenu === item.label
              return (
                <div
                  className="header__nav-item"
                  key={item.label}
                  ref={node => {
                    if (node) menuRefs.current.set(item.label, node)
                    else menuRefs.current.delete(item.label)
                  }}
                >
                  <button
                    type="button"
                    className={
                      "header__nav-link" + (menuActive(item) ? " header__nav-link--active" : "")
                    }
                    aria-expanded={open}
                    aria-haspopup="true"
                    onClick={() => toggleMenu(item.label)}
                  >
                    {item.label}
                    <Icon
                      name="chevronDown"
                      size={14}
                      className={"header__nav-caret" + (open ? " header__nav-caret--open" : "")}
                    />
                  </button>
                  {open && menuRect && (
                    <div
                      className="header__dropdown"
                      style={{ top: menuRect.top + "px", left: menuRect.left + "px" }}
                    >
                      {item.children.map(child => (
                        <Link className="header__dropdown-link" to={child.to} key={child.to}>
                          <span className="header__dropdown-title">{child.label}</span>
                          <span className="header__dropdown-desc">{child.desc}</span>
                        </Link>
                      ))}
                    </div>
                  )}
                </div>
              )
            }
            return (
              <div className="header__nav-item" key={item.to}>
                <Link
                  className={
                    "header__nav-link" + (isActive(item.to) ? " header__nav-link--active" : "")
                  }
                  to={item.to}
                >
                  {item.label}
                </Link>
              </div>
            )
          })}
        </nav>

        <div className="header__tools">
          <span className="header__status">
            <span
              className={
                "header__status-dot" +
                (status.isOpen ? " header__status-dot--open" : " header__status-dot--closed")
              }
            />
            <span className="header__status-text">{status.label}</span>
          </span>

          <label className="header__search" htmlFor="header-search">
            <Icon name="search" size={15} className="header__search-icon" />
            <input
              id="header-search"
              className="header__search-input"
              type="search"
              placeholder="Search ticker"
              autoComplete="off"
            />
          </label>

          <button
            type="button"
            className="header__menu-toggle"
            aria-label={mobileOpen ? "Close menu" : "Open menu"}
            aria-expanded={mobileOpen}
            onClick={() => setMobileOpen(open => !open)}
          >
            <Icon name={mobileOpen ? "close" : "menu"} size={18} />
          </button>

          <AccountMenu />
        </div>
      </div>

      <div className={"header__mobile-nav" + (mobileOpen ? " header__mobile-nav--open" : "")}>
        {flatItems.map(item => (
          <Link
            className={
              "header__mobile-link" + (isActive(item.to) ? " header__mobile-link--active" : "")
            }
            to={item.to}
            key={item.to}
          >
            {item.label}
          </Link>
        ))}
        {/* Every dropdown becomes its own labelled group. Nothing is dropped. */}
        {menuItems.map(item => (
          <div className="header__mobile-group" key={item.label}>
            <p className="header__mobile-label">{item.label}</p>
            {item.children.map(child => (
              <Link
                className={
                  "header__mobile-link" + (isActive(child.to) ? " header__mobile-link--active" : "")
                }
                to={child.to}
                key={child.to}
              >
                {child.label}
              </Link>
            ))}
          </div>
        ))}
      </div>
    </header>
  )
}
