import React, { useEffect, useState, useSyncExternalStore } from "react"

import { loadRemoteData } from "../../data/remote.js"
import { adopt, subscribe, dataVersion, dataOrigin, noteRemoteError } from "../../data/store.js"
import { isConfigured } from "../../data/supabase.js"

/**
 * Boots the runtime data load, once, for the whole app.
 *
 * The site is statically rendered, so the first paint always uses the bundled
 * data — there is no waiting for a network call before anything appears. This
 * kicks off the Supabase read afterwards and, if it returns something usable,
 * swaps it in. Components re-render because they subscribe to the store's
 * version counter.
 *
 * WHY THERE IS NO LOADING STATE
 * A spinner would be a lie. The data is already on screen and already valid —
 * what is pending is whether there is something newer. Blanking a working
 * terminal to wait for that would be strictly worse than showing it.
 *
 * Failures are recorded rather than surfaced. A visitor does not need to know
 * that a refresh check failed while they are looking at yesterday's close;
 * the Data Management screen is where that belongs, and it reads the same
 * recorded error.
 */

/*
 * useSyncExternalStore is the right primitive here specifically because of
 * hydration: it takes a separate server snapshot, so the markup React renders
 * on the client for the first pass matches the HTML Gatsby built even if the
 * store has already been updated. Subscribing with useEffect instead would
 * produce a hydration mismatch the moment a fast network beat hydration.
 */
const serverVersion = () => 0

export function useDataVersion() {
  return useSyncExternalStore(subscribe, dataVersion, serverVersion)
}

/** Re-render on every data swap, and report where the data came from. */
export function useDataOrigin() {
  useDataVersion()
  return dataOrigin()
}

export default function DataProvider({ children }) {
  const [, setReady] = useState(false)

  useEffect(() => {
    if (!isConfigured) return undefined

    let cancelled = false

    loadRemoteData()
      .then(result => {
        if (cancelled) return

        if (result.ok && adopt(result.payload)) {
          setReady(true)
          return
        }

        /*
         * Everything that lands here keeps the bundled data, which is the
         * point. "empty" and "not-configured" are expected states on a fresh
         * project and are not worth recording as errors — the others are,
         * because somebody will need to know why the refresh isn't landing.
         */
        if (result.reason !== "empty" && result.reason !== "not-configured") {
          noteRemoteError(result.error || new Error(result.reason))
        }
      })
      .catch(error => {
        if (!cancelled) noteRemoteError(error)
      })

    return () => {
      cancelled = true
    }
  }, [])

  return <>{children}</>
}
